Draw_FlashMemUpdate_message_bitmap:  ; EF5040
	DEC 4, XSP
	PUSH IZ
	LD HL, BC
	LD (XSP + 002h), XWA
	LD IY, HL
	LD IX, DE
	INC 1, IX
	LD IZ, 0

