	LD WA, IZ
	EXTZ XWA
	DIV WA, 001ch ; 28 bytes = 224 pixels de largura da imagem a ser desenhada
	LD WA, QWA
	CP WA, 0
	JR NZ, LABEL_EF5063
	LD IY, HL ; IY = coordanada X do canto esquerdo da imagem a ser desenhada
	DEC 1, IX

