	LD QHL 0

LABEL_EF5066:
	LD DE, IZ
	EXTZ XDE
	ADD XDE, (XSP + 002h)
	LDA XWA, 0E36Ah       ; table of bit masks (equivalent to 1044h on boot "table_data" rom)
	LD BC, QHL
	EXTZ XBC
	ADD XBC, XWA  ; indexing bit masks with value of QHL
	LD A, (XBC)
	AND A, (XDE)  ; here XDE points at one of the bytes of the image we're drawing and we select the bit we need
	LD QIXL, A
	LD DE, IX
	EXTZ XDE
	LDA XBC, 043C00h   ; aparentemente isso é um buffer offscreen

