LABEL_EF50AA:
	LD DE, IY
	INC 1, IY
	EXTZ XDE
	ADD XWA, XDE   ; XWA = 320*y + x
	LD XDE, XBC
	ADD XDE, XWA   ; XDE = offscreen_buffer[320*y + x]
	LD A, (XSP + 00ch)
	LD (XDE), A

LABEL_EF50BB:
	INC 1, QHL
	CP QHL, 0008h
	JR C, LABEL_EF5066
	INC 1, IZ
	CP IZ, 0268h     ; 28 bytes (224 pixels/line) * 22 lines = 0268h bytes
	JR C, LABEL_EF5050
	LDA XWA, 1A0000h ; memoria de video
	LD DE, 9600h ; 320x120 words = 320x240 pixels
	CALL Copy_DE_words_from_XBC_to_XWA  ; <-- "blit-screen"
	POP IZ
	INC 4, XSP
	RETD, 0004h

LABEL_EF50DF:
	DEC 6, XSP
