	LD (XSP + 008h), WA
	LD IX, BC
	LD (XSP + 004h), BC
	ADD (XSP + 004h), 000ch
	CP IX, (XSP + 004h)
	JR NC, LABEL_EF513D

LABEL_EF50F7:
	LD IY, (XSP + 008h)
	LD BC, IY
	INC 6, BC
	CP IY, BC
	JR NC, LABEL_EF5136

LABEL_EF5102:
	LD DE, IY
	EXTZ XDE
	LD WA, IX
	EXTZ XWA
	LD XHL, XWA
	SLL 2, XHL
	ADD XHL, XWA
	SLL 6, XHL
	ADD XHL, XDE
	SRL 1, XHL
	ADD XHL, XHL
	LD XIZ, 001a0000h
	ADD XIZ, XHL
	LD A, (XSP + 006h)
	EXTZ WA
	LD DE, WA
	SLL 8, DE
	OR WA DE
	LD (XIZ), WA
	INC 2, IY
	CP IY, BC
	JR C, LABEL_EF5102

LABEL_EF5136:
