	LD DE, 0

LABEL_EF5143:
	INC 1, DE
	CP DE, 0100h
	JR C, LABEL_EF5143
	EXTZ XWA
	LD XDE, 00170000h
	ADD XDE, XWA
	LD (XDE), C
	RET

Read_VGA_Register:
	EXTZ XWA
	LD XBC, 00170000h
	ADD XBC, XWA
	LD L, (XBC)
	RET

MACRO VGA_WRITE(register, value)
	LD WA, 0x#register
	LD BC, 0x#value
	CALR Write_VGA_Register
ENDMACRO

MACRO PALLETE_WRITE(red, green, blue)
	LD WA, 03ch9
	LD BC, 0x#red
	CALR Write_VGA_Register
	LD BC, 0x#green
	CALR Write_VGA_Register
	LD BC, 0x#blue
	CALR Write_VGA_Register
ENDMACRO

MACRO VGA_ATTRIBUTE(field, value)
	VGA_WRITE(3c0, #field)
	VGA_WRITE(3c0, #value)
ENDMACRO

MACRO VGA_SEQUENCER(field, value)
	VGA_WRITE(3c4, #field)
	VGA_WRITE(3c5, #value)
ENDMACRO

MACRO VGA_GFX_CONTROLLER(field, value)
	VGA_WRITE(3ce, #field)
	VGA_WRITE(3cf, #value)
ENDMACRO

MACRO VGA_COLOR_CRTC(field, value)
	VGA_WRITE(3d4, #field)
	VGA_WRITE(3d5, #value)
ENDMACRO


