	LDA XSP, XSP - 010h
	PUSH XIZ
	LD (XSP + 010h), XWA
	LD XBC, (XSP + 010h)
	LDA XWA, XBC + 00eh
	LD (XSP + 008h), XWA
	LD (XSP + 004h), XBC
	LD XWA, XBC
	LD XWA, (XWA + 00ah)
	ADD (XSP + 004h), XWA
	LD WA, 03c8h
	LD BC, 0
	CALR _Write_VGA_Register
	LD XIZ, 0

LABEL_FB3F8C:
