	LD C, (XWA + 002h)
	SRL 4, C
	EXTZ BC
	LD WA, 03c9h
	CALR _Write_VGA_Register
	LD XWA, (XSP + 00ch)
	LD C, (XWA + 001h)
	SRL 4, C
	EXTZ BC
	LD WA, 03c9h
	CALR _Write_VGA_Register
	LD XWA, (XSP + 00ch)
	LD C, (XWA)
	SRL 4, C
	EXTZ BC
	LD WA, 03c9h
	CALR _Write_VGA_Register
	INC 4, XIZ
	CP XIZ, 00000400h
	JR C, LABEL_FB3F8C
	LD XIZ, 0
	LD XWA, (XSP + 008h)
	LDA XDE, XWA + 014h
	LD XWA, (XDE)
	CP XWA, 00000000h
	JR ULE, LABEL_FB4011
	LD XIX, (XSP + 004h)
	LD XWA, XIX
	LDA XHL, XWA + 001h
	LD XBC, 0

LABEL_FB3FF0:
	LD A, (XIX)
	LD IYL A
	EXTZ IY
	LD A, (XHL)
	EXTZ WA
	SLL 8, IY
	OR IY WA
	LD XWA, 001a0000h
	ADD XWA, XBC
	LD (XWA), IY
	INC 1, XIZ
	INC 2, XBC
	CP XIZ, (XDE)
	JR C, LABEL_FB3FF0

