SOME_CPANEL_ROUTINE__FC3EF5:
	LD XHL, SomeCpanelData
	LD (XHL - 4), 0000h
	LD (XHL - 8), 0000h
	LD (XHL - 2), 0080h

	LD XHL, SomeOtherCpanelData
	LD (XHL - 4), 0000h
	LD (XHL - 8), 0000h
	LD (XHL - 2), 0080h

	LD A, 003h ; PF2=SCK0 Disabled, PF0=TxD0 and PF1=RXD0 (MIDI)
	AND A, 0afh ; PF6=SCK1 Disabled, PF4=TxD1 and PF5=RXD1 (Control Panel)
	LD (PFFC_VALUE), A
	LD (PFFC), A
	LD A, 015h
	AND A, 08fh
	LD (PFCR_VALUE), A
	LD (PFCR), A
	AND (PF), 0bfh ; PF bit 6, (SCLK1 | /CTS1) = 0
	LD A, 000h
	LD (PEFC), A
	LD A, 046h
	LD (PECR), A
	LD (SC1MOD), 000h ; serial clk: TO2 trigger
	                  ; serial transfer mode: I/O  transfer mode
	                  ; wake-up function: disable
	                  ; receive control: receive disable
	                  ; handshake function control: CTS disable
	LD (BR1CR), 014h ; Internal Clock T2 (16/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/16/4 = 250kHz
	LD (SC1CR), 001h ; Parity: odd
	                 ; Parity addition: disable
	                 ; clear all errors
	                 ; Data transmit/receive at SCLK1 rising edge
	                 ; I/O interface input clock: SCLK1 pin input
	LD (INTEAB), 007h
	LD (INTCLR), 012h ; INTA Pin
	LD (INTES1), 0ffh
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	OR (TAMOD), 010h
	AND (TAMOD), 0f7h
	LD (CPANEL_UNUSED_1), 07dh  ; This looks pointless...

	OR (CPANEL_SERIAL_FLAGS_A), 040h ; CP_Flags_A.6 = 1
	LD (CPANEL_STATE_0_TO_17), 000h
	AND (CPANEL_SERIAL_FLAGS_A), 0fch ; CP_Flags_A.10 = 00
	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	LD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0000h
	LD (CPANEL_BACKUP_RX_INDEX), 0000h
	LD (CPANEL_RX_INDEX), 0000h

	CALR DELAY_6_TICKS

	LD A, 01fh
	LD W, 0dah
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	CALR DELAY_3000_LOOPS

	CALR LABEL_FC3FA9
	RET


LABEL_FC3FA9:
	LD A, 01fh
	LD W, 01ah
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	CALR DELAY_3000_LOOPS

	LD A, 01dh
	LD W, 000h
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	LD A, 0ddh
	LD W, 003h
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	LD A, 01eh
	LD W, 080h
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	EI 006h
	LD (INTES1), 0ffh
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: receive disable
	LD (INTCLR), 012h ; INTA Pin
	LD (INTEAB), 005h
	LD (CPANEL_BACKUP_RX_INDEX), 0000h
	LD (CPANEL_RX_INDEX), 0000h
	OR (CPANEL_SERIAL_FLAGS_B), 001h		; CP_Flags_B.0 = 1
	EI 000h
	RET


