SEND_SOME_CPANEL_COMMANDS__FC41FC:
	LD XHL, SomeCpanelData
	LD (XHL - 4), 0000h
	LD (XHL - 8), 0000h
	LD (XHL - 2), 0080h

	EI 006h
	LD WA, (CPANEL_BACKUP_RX_INDEX)
	LD (CPANEL_RX_INDEX), WA
	OR (CPANEL_SERIAL_FLAGS_B), 001h		; CP_Flags_B.0 = 1
