CHECK_IF_WE_ARE_READY_TO_SEND_CMD_TO_CPANEL:
	LD (CPANEL_COUNTER_DOWN_FROM_200), 0c8h ; =200

LABEL_FC437A:
	EI 006h
	BIT 6, (PF)		; PF.6 = state of SCLK1 pin == 1, (resting at pull-up)
	JR Z, LABEL_FC4394
	BIT 5, (PE)		; PE.5 = state of INTA pin == 0
	JR NZ, LABEL_FC4394
	BIT 1, (CPANEL_SERIAL_FLAGS_A)
	JR NZ, LABEL_FC4394
	BIT 0, (CPANEL_SERIAL_FLAGS_A)
	JR NZ, LABEL_FC4394
	JR T, LABEL_FC43A6

LABEL_FC4394:
	DEC 1, (CPANEL_COUNTER_DOWN_FROM_200)
	CP (CPANEL_COUNTER_DOWN_FROM_200), 000h
	JR Z, LABEL_FC43B0
	EI 000h
	CALR DELAY_1500_LOOPS
	JR T, LABEL_FC437A

LABEL_FC43A6:
	; Only reaches here when CP_Flags_A.10 == 00, and I think only CPANEL_SERIAL_ROUTINE_0 sets that value...

	LD WA, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	CP WA, (CPANEL_INDEX_FOR_LEDS)
	JR NZ, LABEL_FC4394

LABEL_FC43B0:
	EI 006h
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	LD (INTES1), 0ddh
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: receive disable
	OR (CPANEL_SERIAL_FLAGS_B), 080h	; CP_Flags_B.7 = 1
	EI 000h
	RET


SEND_CMD_TO_CPANEL:
	EI 006h
	LD (CPANEL_INDEX_FOR_LEDS), 0000h
	LD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0000h
	LD (CPANEL_ARRAY__STATE_OF_LEDS), WA
	ADD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0002h
	OR (CPANEL_SERIAL_FLAGS_A), 002h
	AND (CPANEL_SERIAL_FLAGS_A), 0feh	; CP_Flags_A.10 = 2
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 004h		; ROUTINE_1
	LD (BR1CR), 028h ; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	AND (PFFC_VALUE), 0bfh ; disable CPanel serial ckl
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	AND (PF), 0bfh 		; PF bit 6: SCLK1 = 0
	OR (PFCR_VALUE), 040h
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (INTEAB), 007h
	LD (INTCLR), 012h ; INTA Pin
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: CPanel receive disable
	AND (SC1CR), 0feh  ; IOC (bit 0) = 0: I/O interface input clock select = Baud rate generator 
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	LD (INTES1), 0dfh
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (SC1BUF), A
	EI 000h
	NOP
	RET


INTA_HANDLER:					; fc442b
	LD (CPANEL_COUNTER_UP_TO_20), 000h
	PUSH XWA
	CP (CPANEL_STATE_0_TO_17), 000h
	JR NZ, LABEL_FC4462

	AND (PFCR_VALUE), 09fh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	OR (SC1CR), 001h	; IOC (bit 0) = 1: Set I/O interface input clock select to SCLK1 pin
	AND (SC1CR), 0fdh	; SCLKS (bit 1) = 0: Data transmit/receive at SCLK1 rising edge.
	LD (INTEAB), 005h
	LD (INTES1), 00dh
	OR (SC1MOD), 020h  ; parity addition: enable
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 020h;		ROUTINE_7
	OR (CPANEL_SERIAL_FLAGS_A), 001h ; CP_Flags_A.0 = 1
	JR T, INTA_HANDLER_END

LABEL_FC4462:
	CP (CPANEL_RX_INDEX), 0000h
	JR NZ, LABEL_FC4470

	LD (CPANEL_RX_INDEX), 005ch

LABEL_FC4470:
	DECW 1, (CPANEL_RX_INDEX)
	OR (CPANEL_SERIAL_FLAGS_B), 040h	; CP_Flags_B.6 = 1  // UNUSED
	AND (CPANEL_SERIAL_FLAGS_A), 0fdh	; CP_Flags_A.1 = 0

INTA_HANDLER_END:      ; FC447E
	POP XWA
	LD (INTCLR), 012h ; INTA Pin
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	RETI


CPANEL_SERIAL_ROUTINES_LIST:		; FC4489
	dd CPANEL_SERIAL_ROUTINE_0 (offsets: 000h)  // IDLE
	dd CPANEL_SERIAL_ROUTINE_1 (         004h)  
	dd CPANEL_SERIAL_ROUTINE_2 (         008h)
	dd CPANEL_SERIAL_ROUTINE_3 (         00ch)
	dd CPANEL_SERIAL_ROUTINE_4 (         010h)
	dd CPANEL_SERIAL_ROUTINE_5 (         014h)
	dd CPANEL_SERIAL_ROUTINE_6 (         018h)
	dd CPANEL_SERIAL_ROUTINE_0 (         01ch)  
	dd CPANEL_SERIAL_ROUTINE_7 (         020h)  // READ_BUTTONS_STATE_1
	dd CPANEL_SERIAL_ROUTINE_8 (         024h)  // READ_BUTTONS_STATE_2
	dd CPANEL_SERIAL_ROUTINE_0 (         028h)  // UNREACHABLE_STATE (?)


INTTX1_HANDLER:   ; FC44B5
	PUSH XWA
	PUSH XHL
	PUSH XIY
	LD L, (CPANEL_SELECT_SERIAL_ROUTINE)
	XOR H, H
	EXTZ XHL
	ADD XHL, CPANEL_SERIAL_ROUTINES_LIST
	LD XHL, (XHL)
	JP T, XHL


MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:		; FC44CA
	POP XIY
	POP XHL
	POP XWA
	LD (INTCLR), 012h ; INTA Pin
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	RETI


INTRX1_HANDLER:   ; FC44D7
	PUSH XWA
	PUSH XHL
	PUSH XIY
	LD L, (CPANEL_SELECT_SERIAL_ROUTINE)
	XOR H, H
	EXTZ XHL
	ADD XHL, CPANEL_SERIAL_ROUTINES_LIST
	LD XHL, (XHL)
	JP T, XHL

LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:			; FC44EC
	POP XIY
	POP XHL
	POP XWA
	LD (INTCLR), 012h ; INTA Pin
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	RETI


CPANEL_SERIAL_ROUTINE_1:        ; FC44F9	// Start transmitting command to set LEDs on the control panel... (?)
	AND (PFCR_VALUE), 0bfh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (BR1CR), 024h ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	LD (INTEAB), 007h ; INTTRA(TREGA): M=7
	LD (INTES1), 0d0h ; INTTX1: M=5
	AND (SC1CR), 0feh
	LD (SC1BUF), A
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next = ROUTINE_2
	MUL A, 001h
	MUL A, 001h
	BIT 6, (PF)		; PF.6 = state of SCLK1 pin
	JR NZ, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


						; If we receive a SCLK1 LOW, does it mean CPANEL is trying to spreak and we revert to IDLE state (ROUTINE_0) ?
	LD (CPANEL_STATE_0_TO_17), 000h
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 000h ; ROUTINE_0
	OR (CPANEL_SERIAL_FLAGS_B), 002h	; CP_Flags_B.1 = 1  // UNUSED
	LD (INTEAB), 005h
	LD (INTES1), 0ffh
	LD (BR1CR), 024h ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	AND (CPANEL_SERIAL_FLAGS_A), 0fdh ; CP_Flags_A.1 = 0
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_3:       ; FC4544
	CALR DELAY_10_LOOPS
	AND (PFCR_VALUE), 0afh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (PFFC_VALUE), 0afh ; disable CPanel serial clk and TX pin.
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	LD (BR1CR), 024h ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	LD (INTES1), 0d0h ; INTTX1: M=5
	AND (SC1CR), 0feh
	LD (SC1BUF), A
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next routine
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_5:       ; FC4573
	CALR DELAY_10_LOOPS
	AND (PFCR_VALUE), 0afh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (PFFC_VALUE), 0afh ; disable CPanel serial clk and TX pin.
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	LD (BR1CR), 024h ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	LD (SC1BUF), A
	LD (INTEAB), 005h
	LD (INTES1), 0d0h ; INTTX1: M=5
	AND (SC1CR), 0feh
	LD (SC1BUF), A
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next routine
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_2:      ; FC45A8
	LD (BR1CR), 014h ; Internal Clock T2 (16/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/16/4 = 250kHz
	OR (PFFC_VALUE), 050h ; Enable CPanel serial clk and TX pin.
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	OR (PFCR_VALUE), 050h
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (SC1CR), 0feh
	LD (INTEAB), 005h
	LD (INTES1), 0d0h ; INTTX1: M=5
	LD XIY, CPANEL_ARRAY__STATE_OF_LEDS
	ADD IY (CPANEL_INDEX_FOR_LEDS)
	LD A, (XIY)
	LD (SC1BUF), A
	INCW 1, (CPANEL_INDEX_FOR_LEDS)
	CP (CPANEL_INDEX_FOR_LEDS), 003ch
	JR C, LABEL_FC45ED
	LD (CPANEL_INDEX_FOR_LEDS), 0000h

LABEL_FC45ED:
	LD (CPANEL_STATE_0_TO_17), 002h
	LD A, (XIY)
	AND A, 03fh
	CP A, 030h
	JR C, LABEL_FC4606
	AND A, 00fh
	ADD A, 003h
	LD (CPANEL_STATE_0_TO_17), A

LABEL_FC4606:
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next = ROUTINE_3
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_4:       ; FC460D
	LD (BR1CR), 014h ; Internal Clock T2 (16/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/16/4 = 250kHz
	OR (PFFC_VALUE), 050h ; Enable CPanel serial clk and TX pin.
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	OR (PFCR_VALUE), 050h
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (SC1CR), 0feh
	LD (INTEAB), 005h
	LD (INTES1), 0d0h ; INTTX1: M=5
	LD XIY, CPANEL_ARRAY__STATE_OF_LEDS
	ADD IY (CPANEL_INDEX_FOR_LEDS)
	LD A, (XIY)
	LD (SC1BUF), A
	INCW 1, (CPANEL_INDEX_FOR_LEDS)
	CP (CPANEL_INDEX_FOR_LEDS), 003ch
	JR C, LABEL_FC4652
	LD (CPANEL_INDEX_FOR_LEDS), 0000h

LABEL_FC4652:
	DEC 1, (CPANEL_STATE_0_TO_17)
	CP (CPANEL_STATE_0_TO_17), 001h
	JR Z, LABEL_FC466B
	CP (CPANEL_STATE_0_TO_17), 000h
	JR Z, LABEL_FC466B
	DEC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; previous routine
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES

LABEL_FC466B:
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next routine
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_6:       ; FC4672
	LD (CPANEL_STATE_0_TO_17), 000h
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 000h ; ROUTINE_0
	LD WA, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	SUB WA, (CPANEL_INDEX_FOR_LEDS)
	CP WA, 2
	JR C, LABEL_FC46C1
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 004h ; ROUTINE_1
	AND (PFFC_VALUE), 0bfh  ; disable CPanel serial clk
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	AND (PF), 0bfh ; PF bit 6, (SCLK1 | /CTS1) = 0
	OR (PFCR_VALUE), 040h
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (BR1CR), 028h ; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	LD (INTEAB), 007h
	AND (SC1CR), 0feh
	LD (INTES1), 0d0h ; INTTX1: M=5
	LD (SC1BUF), A
	OR (CPANEL_SERIAL_FLAGS_A), 002h ; CP_Flags_A.1 = 1 
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES

LABEL_FC46C1:
	AND (PFCR_VALUE), 0bfh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (PFFC_VALUE), 0bfh ; disable CPanel serial clk
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	LD (INTEAB), 005h
	LD (INTES1), 0ffh ; INTTX1: M=7 | INTRX1: M=7 (meaning: disable int.req.)
	LD (BR1CR), 024h ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	AND (CPANEL_SERIAL_FLAGS_A), 0fdh ; CP_Flags_A.1 = 0
	JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_7:        ; FC46EA
	AND (PFCR_VALUE), 09fh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	OR (SC1CR), 001h
	AND (SC1CR), 0fdh
	LD (INTEAB), 005h
	LD (INTES1), 00dh
	LD A, (SC1BUF)
	LD XIY, CPANEL_RX_DATA
	ADD IY (CPANEL_RX_INDEX)
	LD (XIY), A
	LD HL, (CPANEL_RX_INDEX)
	SUB HL, (CPANEL_BACKUP_RX_INDEX)
	JR NC, LABEL_FC4722
	NEG HL
	LD IY, HL
	JR T, LABEL_FC4727

LABEL_FC4722:
	LD IY, 005ch
	SUB IY, HL

LABEL_FC4727:
	CP IY, 3
	JR NC, LABEL_FC4732
	OR (CPANEL_SERIAL_FLAGS_B), 001h	; CP_Flags_B.0 = 1
	JR T, LABEL_FC4749

LABEL_FC4732:
	AND (CPANEL_SERIAL_FLAGS_B), 0feh	; CP_Flags_B.0 = 0
	INCW 1, (CPANEL_RX_INDEX)
	CP (CPANEL_RX_INDEX), 005ch
	JR C, LABEL_FC4749
	LD (CPANEL_RX_INDEX), 0000h

LABEL_FC4749:
	LD (CPANEL_STATE_0_TO_17), 002h
	AND A, 03fh
	CP A, 030h
	JR C, LABEL_FC4760
	AND A, 00fh
	ADD A, 003h
	LD (CPANEL_STATE_0_TO_17), A

LABEL_FC4760:
	INC 4, (CPANEL_SELECT_SERIAL_ROUTINE) ; next routine
	JRL T, LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_8:       ; FC4767
	LD A, (SC1BUF)
	LD XIY, CPANEL_RX_DATA
	ADD IY (CPANEL_RX_INDEX)
	LD (XIY), A
	BIT 0, (CPANEL_SERIAL_FLAGS_B)			; CP_Flags_B.0	
	JR NZ, LABEL_FC478D
	INCW 1, (CPANEL_RX_INDEX)
	CP (CPANEL_RX_INDEX), 005ch
	JR C, LABEL_FC478D
	LD (CPANEL_RX_INDEX), 0000h

LABEL_FC478D:
	DEC 1, (CPANEL_STATE_0_TO_17)
	CP (CPANEL_STATE_0_TO_17), 001h
	JR NZ, LABEL_FC47CC
	LD (CPANEL_STATE_0_TO_17), 000h
	AND (CPANEL_SERIAL_FLAGS_A), 0feh ; CP_Flags_A.0 = 0
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 000h ; ROUTINE_0
	AND (PFCR_VALUE), 09fh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	AND (PFFC_VALUE), 0bfh ; disable CPanel serial clk
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	LD (INTEAB), 005h
	LD (INTES1), 00dh
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: receive disable
	JRL T, LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES

LABEL_FC47CC:
	AND (PFCR_VALUE), 09fh
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	OR (SC1CR), 001h
	AND (SC1CR), 0fdh
	LD (INTEAB), 005h
	LD (INTES1), 00dh
	JRL T, LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPANEL_SERIAL_ROUTINE_0:       ; FC47E9		// CPANEL_SERIAL_IDLE_STATE (?)
	OR (CPANEL_SERIAL_FLAGS_B), 080h	; CP_Flags_B.7 = 1
	JRL T, LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES

	AND (CPANEL_SERIAL_FLAGS_A), 0fch 	; CP_Flags_A.0 = 0
						; CP_Flags_A.1 = 0
	OR (CPANEL_SERIAL_FLAGS_B), 004h	; CP_Flags_B.2 = 1  // UNUSED
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: receive disable
	LD (INTES1), 00fh
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTEAB), 007h
	LD (INTCLR), 012h ; INTA Pin
	RETI


LABEL_FC480F:
	INC 1, (CPANEL_COUNTER_UP_TO_42)
	CP (CPANEL_COUNTER_UP_TO_42), 02ah     ; =42 ;-)
	JR ULE, LABEL_FC485B
	EI 006h
	LD WA, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	SUB WA, (CPANEL_INDEX_FOR_LEDS)
	JR NC, LABEL_FC482C
	NEG WA
	LD HL, WA
	JR T, LABEL_FC4831

LABEL_FC482C:
	LD HL, 003ch
	SUB HL, WA

LABEL_FC4831:
	CP HL, 3
	JR C, LABEL_FC485B
	LD (CPANEL_COUNTER_UP_TO_42), 000h
	LD W, 0e0h
	LD A, 013h
	LD IY, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	LD XDE, CPANEL_ARRAY__STATE_OF_LEDS
	LD (XDE + IY), W
	CALR INC_IY_MOD_03Ch
	LD (XDE + IY), A
	CALR INC_IY_MOD_03Ch
	LD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), IY


0 => 0 do_this
1 => 2 do_this
2 => 3 do_this
3 => 0 do_that

LABEL_FC485B:
	EI 000h
	LD A, (CPANEL_SERIAL_FLAGS_A)
	AND A, 0c0h
	CP A, 0					; if (CP_Flags_A.76 == 0) {
	JR Z, LABEL_FC4877			; 	goto LABEL_FC4877; //do this
						; }


	ADD (CPANEL_SERIAL_FLAGS_A), 040h
	CP A, 0c0h
	JR NZ, LABEL_FC4877 	; if (CP_Flags_A.76++ == 3) {

	CALR LABEL_FC42FB // do that

	JR T, LABEL_FC487A
				; } else {

LABEL_FC4877:
	CALR LABEL_FC4B2D // do this
				; }
LABEL_FC487A:
	EI 006h
	BIT 6, (PF)		; PF.6 = state of SCLK1 pin
	JR Z, LABEL_FC48EB
	BIT 5, (PE)		; PE.5 = state of INTA pin
	JR NZ, LABEL_FC48EB
	BIT 1, (CPANEL_SERIAL_FLAGS_A)
	JR NZ, LABEL_FC48EB
	BIT 0, (CPANEL_SERIAL_FLAGS_A)
	JR NZ, LABEL_FC48EB
	
	; Only reaches here when (CPANEL_SERIAL_FLAGS_A), CP_Flags_A.10 == 00:
	LD WA, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	SUB WA, (CPANEL_INDEX_FOR_LEDS)
	JR NC, LABEL_FC48A4
	NEG WA
	EX A, W
	LD A, 03ch
	SUB A, W

LABEL_FC48A4:
	CP A, 2
	JR C, LABEL_FC48E8
	OR (CPANEL_SERIAL_FLAGS_A), 002h		; CP_Flags_A.1 = 1
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 004h; ROUTINE_1
	AND (PFFC_VALUE), 0bfh ; disable CPanel serial clk
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	AND (PF), 0bfh ; PF bit 6, (SCLK1 | /CTS1) = 0
	OR (PFCR_VALUE), 040h
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (BR1CR), 028h ; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	AND (SC1MOD), 0dfh  ; RXE (bit 5) = 0: CPanel receive disable
	AND (SC1CR), 0feh
	LD (INTEAB), 007h
	LD (INTCLR), 012h ; INTA Pin
	LD (INTCLR), 023h ; INTTX1: Serial send 1 
	LD (INTES1), 0d0h
	LD (SC1BUF), A

LABEL_FC48E8:
	EI 000h
	RET


LABEL_FC48EB:
	INC 1, (CPANEL_COUNTER_UP_TO_20)
	CP (CPANEL_COUNTER_UP_TO_20), 014h
	JR ULE, LABEL_FC48E8

	EI 006h
	LD (INTCLR), 022h ; INTRX1: Serial receive 1
	LD (INTCLR), 023h ; INTTX1: Serial send 1
	LD (INTES1), 0ddh
	LD (INTCLR), 012h ; INTA Pin
	LD (INTEAB), 005h
	OR (CPANEL_SERIAL_FLAGS_B), 080h	; CP_Flags_B.7 = 1
	JR T, LABEL_FC48E8




LABEL_FC490E:
	OR (CPANEL_SERIAL_FLAGS_A), 004h ; CP_Flags_A.2 = 1  // UNUSED?
	JR T, LABEL_FC491A

LABEL_FC4915:
