LABEL_FC491A:
	LD XDE, CPANEL_RX_DATA
	LD IY, (CPANEL_BACKUP_RX_INDEX)
	LD XIZ, SomeCpanelData
	LD IX, (XIZ - 4)

LABEL_FC492B:
