	CALR INC_IY_MOD_05Ch
	LD (XIZ + IX), W
	CALR INC_IX_MOD_080h
	LD (CPANEL_UNUSED_2), W
	LD A, (XDE + IY)
	CALR INC_IY_MOD_05Ch
	LD (CPANEL_UNUSED_3), A
	LD C, W
	CALR LABEL_FC4A36
	CP HL, 0ffffh
	JR NZ, LABEL_FC4A14
	CALR DEC_IX_MOD_080h
	LD (CPANEL_BACKUP_RX_INDEX), IY
	JR T, LABEL_FC4A33

LABEL_FC4A14:
