	CALR INC_IX_MOD_080h
	LD (CPANEL_VAR__8D96), L
	LD (XIZ + IX), 0ffh
	CALR INC_IX_MOD_080h
	LD (XIZ - 4), IX
	DECW 3, (XIZ - 2)
