	CALR INC_IY_MOD_05Ch
	LD A, (XDE + IY)
	CALR INC_IY_MOD_05Ch
	AND A, 01fh
	AND C, 0c0h
	OR C, A
	LD W, C
	BIT 004h, W
	JR NZ, LABEL_FC4A8B
	AND C, 040h
	BIT 006h, C
	JR Z, LABEL_FC4A7D
