Set_LEDs:				; FC71B2
	; Input: WA: row of LEDs
	;         C: LED pattern
	LD E, A
	CP E, 00fh
	RET UGT
	LDA XWA, CPANEL_LEDS__ROW_AND_PATTERN_BYTES
	EXTZ DE
	LDA XHL Protocol_values_for_LED_rows
	LD E, (XHL + DE)
	LD (XWA), E
	LD (XWA + 001h), C
	CALR LABEL_FC71D2
	RET

