	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 00ah), DE
	LD (XSP + 00ch), BC
	LD (XSP + 004h), 0000h
	LD XIZ, XWA
	LD XWA, 0
	LD (XSP + 006h), XWA
	LD XHL, XIZ
	AND XHL, 000000ffh
	LD XWA, XHL
	SLL 9, XWA
	ADD XWA, XHL
	LD XHL, XIZ
	SRL 8, XHL
	AND XHL, 000000ffh
	ADD XHL, XWA
	LD XWA, XHL
	SLL 9, XWA
	ADD XWA, XHL
	LD XHL, XIZ
	SRL 0, XHL
	AND XHL, 0000001fh
	ADD XHL, XWA
	LD XWA, XHL
	LD XBC, 000007ffh
	CALL LABEL_FF0C12
	LD IX, HL
	JR T, LABEL_FCD282

